## MLM Web App in Node.js

**Product:** ZenFit (fitness tracker)

**Web App:**

```js
const express = require('express');
const app = express();

const products = [
  { name: 'ZenFit Classic', price: 29.99, features: ['heart rate monitor', 'sleep tracker', 'calorie tracker'] },
  { name: 'ZenFit Pro', price: 49.99, features: ['all features of ZenFit Classic', 'GPS tracker', 'voice assistant'] }
];

app.get('/products', (req, res) => {
  res.send(products);
});

app.get('/products/:name', (req, res) => {
  const product = products.find(p => p.name === req.params.name);
  if (product) {
    res.send(product);
  } else {
    res.status(404).send('Product not found');
  }
});

app.post('/orders', (req, res) => {
  const order = req.body;
  const total = order.quantity * products.find(p => p.name === order.product).price;
  order.total = total;
  res.send(order);
});

app.listen(3000);
```

